        "type": "object",
        "properties": {
          "mcpServers": {
            "description": "User configuration values for MCP servers keyed by server name",
            "type": "object",
            "propertyNames": {
              "type": "string"
            },
            "additionalProperties": {
              "type": "object",
              "propertyNames": {
                "type": "string"
